function persist() { try { localStorage.setItem('trippulse-modern-v1', JSON.stringify(state)); } catch { /* The working session continues without persistence. */ } }
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500); }
function button(label,nav,type='',symbol='') { return `<button class="btn ${type}" data-nav="${nav}">${symbol?icon(symbol):''}${label}</button>`; }
function actionButton(label,action,type='secondary',symbol='') { return `<button class="btn ${type}" data-action="${action}">${symbol?icon(symbol):''}${label}</button>`; }
function heading(title,subtitle,action='') { return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`; }
function sectionHeading(title,label='',nav='') { return `<div class="section-heading"><h2>${title}</h2>${label?`<button class="text-button" data-nav="${nav}">${label} ${icon('arrow')}</button>`:''}</div>`; }
function initials(name) { return String(name).trim().split(/\s+/).map(word=>word[0]).slice(0,2).join('').toUpperCase(); }
function avatars(label='Your favorite people') { return `<div class="avatar-stack" aria-label="Trip members">${state.members.slice(0,3).map(member=>`<span class="avatar" title="${escapeHTML(member.name)}">${escapeHTML(initials(member.name))}</span>`).join('')}${state.members.length>3?`<span class="avatar">+${state.members.length-3}</span>`:''}${label?`<small>${label}</small>`:''}</div>`; }
function dateText(date=state.trip.date,short=false) { return new Date(`${date}T12:00:00`).toLocaleDateString('en-GB',{day:'numeric',month:short?'short':'long',...(!short&&{year:'numeric'})}); }
function formatTime(minutes) { const total=Math.round(minutes), hour=Math.floor((total%1440)/60), minute=total%60; return `${hour%12||12}:${String(minute).padStart(2,'0')} ${hour>=12?'PM':'AM'}${total>=1440?' (+1 day)':''}`; }
function startMinutes() { const [hour,minute]=state.trip.time.split(':').map(Number);return hour*60+minute; }
function durationText(minutes) { return `${Math.floor(minutes/60)?`${Math.floor(minutes/60)}h `:''}${minutes%60?`${minutes%60}m`:minutes?'':'0m'}`.trim(); }
function selectedPlaces() { return places.filter(place=>state.selected.includes(place.id)); }
function routeNotice() {
  const custom=state.trip.start.trim().toLowerCase()!=='kandy'||state.trip.destination.trim().toLowerCase()!=='trincomalee';
  return custom||state.trip.transport!=='Car'?`<div class="notice">${icon('info')}<div><strong>Your details are saved. Route estimates remain a sample.</strong><p>Places, the illustrated map, and travel times use the Kandy → Trincomalee driving demo. No new route or transport calculation is performed.</p></div></div>`:'';
}
