function field(label,name,value,type='text',extra='') { return `<label class="field">${label}<input name="${name}" type="${type}" value="${escapeHTML(value)}" ${extra}></label>`; }
function selectField(label,name,options,value) { return `<label class="field">${label}<select name="${name}">${options.map(option=>`<option ${value===option?'selected':''}>${escapeHTML(option)}</option>`).join('')}</select></label>`; }
function createTrip() {
  const interests=['Beaches','Temples','Heritage','Nature','Wildlife','Waterfalls','Hiking','Food','Viewpoints','Adventure','Family Friendly','Budget Friendly'];
  const titles=['Where are we headed?','Make it your kind of trip.','A little more you.'];
  const subtitles=['Start with the journey. The good stops will follow.','Set the pace, pick your people, and leave room for possibility.','Choose what you love. We’ll help make space for it.'];
  let fields='';
  if(formStep===1)fields=`<div class="form-grid"><label class="field full">Trip name<input name="name" value="${escapeHTML(draft.name)}" required maxlength="85" autocomplete="off"></label>${field('Start location','start',draft.start,'text','required maxlength="60"')}${field('Destination','destination',draft.destination,'text','required maxlength="60"')}<div class="field full">${selectField('Transport mode','transport',['Car','Van','Bus','Train','Motorcycle'],draft.transport)}</div></div>`;
  if(formStep===2)fields=`<div class="form-grid">${field('Travel date','date',draft.date,'date','required min="2026-01-01" max="2099-12-31"')}${field('Start time','time',draft.time,'time','required')}${field('Group size','group',draft.group,'number','required min="1" max="50"')}<div class="field"><span>Your travel crew</span><p class="simulation-note">Count yourself in. Invite everyone from your trip workspace.</p></div></div><fieldset><legend class="form-legend">Budget level</legend><div class="option-grid">${[['Low','Keep it simple'],['Medium','A little of everything'],['Premium','A few extra comforts']].map(([name,copy])=>`<button type="button" class="option-card" data-budget="${name}" aria-pressed="${draft.budget===name}"><strong>${name}</strong><small>${copy}</small></button>`).join('')}</div></fieldset>`;
  if(formStep===3)fields=`<fieldset><legend class="form-legend">What draws you in?</legend><div class="chips">${interests.map(interest=>`<button type="button" class="chip" data-interest="${interest}" aria-pressed="${draft.interests.includes(interest)}">${draft.interests.includes(interest)?'✓ ':''}${interest}</button>`).join('')}</div></fieldset><fieldset><legend class="form-legend">Your travel style</legend><div class="option-grid">${[['Relaxed','Fewer stops, more breathing room'],['Balanced','The best of both worlds'],['Packed','Make every moment count']].map(([name,copy])=>`<button type="button" class="option-card" data-style="${name}" aria-pressed="${draft.style===name}"><strong>${name}</strong><small>${copy}</small></button>`).join('')}</div></fieldset><p class="simulation-note section-space">Your preferences are saved locally. Recommendations use the curated Kandy → Trincomalee demo route.</p>`;
  return `${heading('Every good trip starts somewhere.','A few details now. A whole lot to look forward to.')}<div class="progress-steps" aria-label="Trip creation progress">${['Route','Details','Preferences'].map((label,index)=>`${index?'<span class="step-line"></span>':''}<div class="progress-step ${formStep===index+1?'active':formStep>index+1?'done':''}" ${formStep===index+1?'aria-current="step"':''}><span>${formStep>index+1?'✓':index+1}</span>${label}</div>`).join('')}</div><div class="content-grid builder-layout"><form id="trip-form" class="card form-card"><span class="eyebrow overline">STEP ${formStep} OF 3</span><h2>${titles[formStep-1]}</h2><p>${subtitles[formStep-1]}</p>${fields}<div class="form-actions"><button type="button" class="btn secondary" data-action="form-back">← ${formStep===1?'Cancel':'Back'}</button><button class="btn" type="submit">${formStep===3?'Generate Trip Workspace':'Continue'} ${icon('arrow')}</button></div></form><aside class="stack"><section class="card builder-preview">${scene('beach')}<div class="card-pad"><span class="eyebrow overline">A LITTLE PREVIEW</span><h3>${escapeHTML(draft.name||'Your next adventure')}</h3><p class="simulation-note">${escapeHTML(draft.start)} → ${escapeHTML(draft.destination)}</p><div class="detail-grid"><div><small>Travelers</small><strong>${escapeHTML(draft.group)} friends</strong></div><div><small>Your pace</small><strong>${escapeHTML(draft.style)}</strong></div><div><small>Budget</small><strong>${escapeHTML(draft.budget)}</strong></div><div><small>Getting around</small><strong>${escapeHTML(draft.transport)}</strong></div></div></div></section><div class="notice">${icon('spark')}<div><strong>Give your day some breathing room.</strong><p>An early start and a proper lunch break make a long drive feel a little lighter.</p></div></div></aside></div>`;
}
function placeCard(place) { const selected=state.selected.includes(place.id);return `<article class="card place-card ${selected?'selected':''}"><div class="place-image">${scene(place.scene)}<span class="place-order">0${place.id}</span><span class="badge">${place.category}</span></div><div class="place-body"><h3>${place.name}</h3><div class="place-data"><span>${icon('clock')}${place.duration} min visit</span><span>${icon('route')}${place.detour} off route</span><span>${icon('car')}+${place.extra} min detour</span><span>${icon('sun')}${place.best}</span></div><p class="place-reason">${place.reason}</p><div class="button-row"><button class="btn ${selected?'soft':'secondary'} small" data-toggle-place="${place.id}" aria-pressed="${selected}" aria-label="${selected?'Remove':'Add'} ${place.name}">${icon(selected?'check':'plus')}${selected?'Added · Remove':'Add to trip'}</button><button class="text-button" data-place="${place.id}">Details ↗</button></div></div></article>`; }
function suggestions() { return `${heading('Good stops. Great stories.','Thoughtfully picked for your Kandy → Trincomalee route.',`<span class="badge">${icon('route')} In travel order</span>`)}${tripTabs()}${routeNotice()}<div class="notice">${icon('spark')}<div><strong>A route with a little bit of everything.</strong><p>Temples, a scenic pause, a proper lunch, and a coastal finish. Add the stops that speak to you. All estimates are illustrative.</p></div></div><div class="place-grid">${places.map(placeCard).join('')}</div><div class="selection-bar"><div class="selection-count"><span>${state.selected.length}</span><div><strong>places on your route</strong><small>${durationText(selectedPlaces().reduce((sum,place)=>sum+place.duration,0))} of little discoveries</small></div></div>${actionButton('Generate Itinerary','generate','','route')}</div>`; }

// A monotonic route model: removing a stop removes its visit and detour, not the route leg.
function buildSchedule() {
  const schedule=[{time:startMinutes(),title:`Start from ${state.trip.start}`,type:'Departure',travel:0,duration:0,note:'Grab breakfast, meet the crew, and take the open road.'}];
  let clock=startMinutes(), previousPosition=0;
  for(const place of selectedPlaces()) {
    const travel=place.at-previousPosition+place.extra;
    clock+=travel;
    schedule.push({time:clock,title:place.name,type:place.category,travel,duration:place.duration,note:place.note,id:place.id});
    clock+=place.duration;previousPosition=place.at;
  }
  const travel=362-previousPosition;
  clock+=travel;
  schedule.push({time:clock,title:`Check-in / Rest in ${state.trip.destination}`,type:'Rest',travel,duration:0,note:'Settle in, freshen up, and let the evening unfold.'});
  return schedule;
}
function scheduleSummary() {
  const schedule=buildSchedule(), travel=schedule.reduce((total,item)=>total+item.travel,0), stops=schedule.reduce((total,item)=>total+item.duration,0), arrival=schedule.at(-1).time;
  return {schedule,travel,stops,arrival,late:arrival>=20*60,balanced:state.selected.length>=3&&arrival<20*60};
}
function itinerary() {
  const summary=scheduleSummary();
  return `${heading('A little structure. A lot of possibility.','Your day, thoughtfully mapped from the hills to the coast.',actionButton('Save Offline','save-offline','secondary','download'))}${tripTabs()}${routeNotice()}<div class="summary-grid">${[['car','Total travel time',durationText(summary.travel)],['clock','Total stop time',durationText(summary.stops)],['pin','Estimated check-in',formatTime(summary.arrival)],['compass','Realism status',summary.late?'Late finish':summary.balanced?'Balanced':'Easy pace']].map(([symbol,label,value])=>`<div class="card summary-card"><small>${icon(symbol)}${label}</small><strong>${value}</strong></div>`).join('')}</div>
  <div class="notice ${summary.late?'warning':'success'}">${icon(summary.late?'clock':'check')}<div><strong>${summary.late?'Your plan runs into the evening.':summary.balanced?'This plan is balanced. You have enough time for key stops without rushing.':'There’s plenty of breathing room in this plan.'}</strong><p>${summary.late?'Try an earlier departure or remove a longer stop. Beach evening light may be missed.':'Travel and visit times are sample estimates. Keep a little flexibility for road conditions and breaks.'}</p></div></div>
  <div class="content-grid"><div class="timeline">${summary.schedule.map(item=>`<article class="timeline-item"><time class="timeline-time">${formatTime(item.time)}</time><span class="timeline-node"></span><div class="card timeline-card"><div class="split-row"><h3>${escapeHTML(item.title)}</h3><span class="badge">${item.type}</span></div><p>${item.note}</p><div class="trip-meta"><span>${icon('car')}${item.travel?`${durationText(item.travel)} from previous stop`:'Starting point'}</span><span>${icon('clock')}${item.duration?`${item.duration} min visit`:item.type==='Rest'?'Rest of the evening':'Meet & depart'}</span></div></div></article>`).join('')}${!state.selected.length?emptyState('A direct route, for now.','Add a few favorites to make the journey your own.','suggestions','Find a stop'):''}</div><aside class="stack itinerary-sidebar"><div class="card">${scene('beach')}<div class="card-pad"><span class="eyebrow overline">SAVE SOME SPACE FOR THE SEA</span><h3>The best plans leave room.</h3><p class="simulation-note">A short viewpoint visit keeps the day comfortable. The full Sigiriya climb would need more time.</p>${button('Ask AI to improve','ai','soft wide','spark')}${button('Open Map','map','secondary wide','map')}${actionButton('Recalculate','recalculate','secondary wide','refresh')}</div></div><div class="notice">${icon('download')}<div><strong>Take your plan with you.</strong><p>Save Offline downloads a readable text copy, including your selected stops and times.</p></div></div></aside></div>`;
}

function mapCanvas(mini=false) {
  const path='M220 850 260 785 290 710 325 642 380 550 470 450 510 350 580 315 650 260 720 230 790 170 840 130';
  const mapPlaces=mini?places.filter(place=>[2,4,5].includes(place.id)):layers.has('Places')?places.filter(place=>state.selected.includes(place.id)||place.id===mapStop):[];
  return `<div class="map-canvas" ${mini?'role="img" aria-label="Illustrated Kandy to Trincomalee route"':''}><div class="map-terrain terrain-one"></div><div class="map-terrain terrain-two"></div><div class="map-terrain terrain-three"></div><div class="map-water"></div><div class="map-lake"></div><svg class="map-roads" viewBox="0 0 1000 1000" preserveAspectRatio="none" aria-hidden="true"><path class="road-shadow" d="M20 970 205 810 220 660 380 550 360 365 600 220 660 20M40 370 220 460 380 550 570 665 740 960M220 850 370 800 570 665 670 415 790 170 900 50"/><path class="road" d="M20 970 205 810 220 660 380 550 360 365 600 220 660 20M40 370 220 460 380 550 570 665 740 960M220 850 370 800 570 665 670 415 790 170 900 50"/><path class="minor" d="M0 560 220 660 240 900M200 0 260 180 220 460 100 800M380 550 470 450 510 350 610 360 670 415 830 550M470 450 600 520 770 710M580 315 560 130 760 0M650 260 720 230 790 170"/><path class="route-shadow" d="${path}"/><path class="route" d="${path}"/><path class="route-dash" d="${path}"/></svg><span class="map-city start">KANDY</span><span class="map-city end">TRINCOMALEE</span><span class="map-city middle">Dambulla</span><span class="map-city forest">CENTRAL HIGHLANDS</span><span class="map-city ocean">INDIAN OCEAN</span>
  ${mini?'<span class="map-marker start-marker" style="left:22%;top:85%">●</span><span class="map-marker" style="left:79%;top:17%">✓</span>':`<button class="map-marker start-marker ${mapStop===0?'active':''}" style="left:22%;top:85%" data-map-stop="0" aria-label="Start: Kandy" aria-pressed="${mapStop===0}">${icon('home')}</button><button class="map-marker ${mapStop===7?'active':''}" style="left:84%;top:13%" data-map-stop="7" aria-label="Destination: Trincomalee" aria-pressed="${mapStop===7}">${icon('pin')}</button>`}
  ${mapPlaces.map(place=>mini?`<span class="map-marker" style="left:${place.x}%;top:${place.y}%">${place.id}</span>`:`<button class="map-marker ${mapStop===place.id?'active':''}" style="left:${place.x}%;top:${place.y}%" data-map-stop="${place.id}" aria-label="${state.selected.includes(place.id)?'Stop':'Preview stop'} ${place.id}: ${place.name}" aria-pressed="${mapStop===place.id}">${place.id}</button>`).join('')}
  ${!mini&&layers.has('Food')?'<button class="map-marker layer-marker" style="left:57%;top:39%" data-facility="food" aria-label="Sample food stop">'+icon('food')+'</button>':''}
  ${!mini&&layers.has('Safety')?'<button class="map-marker layer-marker safety" style="left:31%;top:51%" data-facility="hospital" aria-label="Sample hospital">'+icon('hospital')+'</button><button class="map-marker layer-marker safety" style="left:72%;top:19%" data-facility="police-station" aria-label="Sample police station">'+icon('shield')+'</button>':''}
  ${!mini&&layers.has('Hotels')?'<button class="map-marker layer-marker hotels" style="left:86%;top:25%" data-facility="hotel" aria-label="Sample coastal hotel">'+icon('hotel')+'</button>':''}
  ${!mini?`<div class="map-float"><strong>Kandy → Trincomalee</strong><small>${selectedPlaces().length} selected stops · ${durationText(scheduleSummary().travel)} sample driving</small></div><span class="map-compass" aria-label="North">N ↑</span><span class="map-footnote">Illustrated preview · Not a navigation map</span>`:''}</div>`;
}
function mapSheet() {
  const place=places.find(item=>item.id===mapStop);
  const title=place?place.name:mapStop===0?'Start in Kandy':'Arrive in Trincomalee';
  return `<div class="card map-sheet" aria-live="polite"><div class="preview-thumb">${scene(place?place.scene:mapStop===0?'hills':'beach')}</div><div><span class="badge">${place?`STOP 0${place.id} · ${place.category}`:mapStop===0?'YOUR STARTING POINT':'YOUR COASTAL DESTINATION'}</span><h3>${title}</h3><p>${place?`${place.duration} min visit · ${place.detour} off route · ${place.best}`:mapStop===0?'Meet your crew and leave a little early.':'Sea air, slow evenings, and time to settle in.'}</p></div><div class="button-row">${place?`<button class="btn secondary small" data-place="${place.id}">Place details ↗</button>`:''}${button('Open Itinerary','itinerary','small','route')}</div></div>`;
}
function mapScreen() { return `${heading('Follow a little curiosity.','Your route, at a glance. Pick a pin to see what’s along the way.',button('Open Itinerary','itinerary','secondary','route'))}${tripTabs()}${routeNotice()}<div class="layer-controls" aria-label="Map layers">${[['Places','pin'],['Food','food'],['Safety','shield'],['Hotels','hotel']].map(([label,symbol])=>`<button class="chip" data-layer="${label}" aria-pressed="${layers.has(label)}">${icon(symbol)}${label}${layers.has(label)?' ✓':''}</button>`).join('')}</div><div class="content-grid"><div><div id="map-visual">${mapCanvas()}</div><div id="map-detail">${mapSheet()}</div></div><aside class="stack"><section class="card"><div class="card-pad"><span class="eyebrow overline">HILLS → CULTURE → COAST</span><h3>Your journey, in order</h3><p class="simulation-note">Select a stop to bring it into focus.</p></div><div class="route-stops"><button class="route-stop" data-map-stop="0"><span>${icon('home')}</span><div><strong>Kandy</strong><small>Your starting point</small></div></button>${selectedPlaces().map(place=>`<button class="route-stop" data-map-stop="${place.id}"><span>${place.id}</span><div><strong>${place.name}</strong><small>${place.duration} min · ${place.category}</small></div></button>`).join('')}<button class="route-stop" data-map-stop="7"><span>${icon('pin')}</span><div><strong>Trincomalee</strong><small>Check-in & a slower evening</small></div></button></div></section><div class="notice">${icon('map')}<div><strong>A beautiful preview, not live directions.</strong><p>Roads, pins, facilities, and travel estimates are illustrative. No map API or device location is used.</p></div></div></aside></div>`; }

function chatMessages() { return `${chat.map(message=>`<div class="chat-message ${message.role}"><span class="avatar ${message.role==='user'?'avatar-main':''}">${message.role==='user'?escapeHTML(initials(state.profile.name)):icon('spark')}</span><div class="chat-bubble">${message.role==='assistant'?'<span class="chat-name">TripPulse AI</span>':''}${escapeHTML(message.text)}${message.safety?`<div class="button-row">${button('Open Safety Center','safety','soft small','shield')}</div>`:''}</div></div>`).join('')}${chatBusy?'<div class="chat-message" role="status" aria-label="TripPulse AI is typing"><span class="avatar">'+icon('spark')+'</span><div class="chat-bubble"><div class="typing-dots"><i></i><i></i><i></i></div></div></div>':''}`; }
function aiScreen() {
  const prompts=['Is this plan realistic?','What should we skip?','Adjust for late start','Suggest cheaper options','Best time for beach?','Find safety help'];
  return `${heading('A little local wisdom, on demand.','Meet the companion that knows your route and leaves room for your curiosity.')}<div class="chat-layout"><section class="card chat-panel"><div class="chat-header"><span class="icon-tile">${icon('spark')}</span><div><h2>TripPulse AI</h2><p>Route-aware planning assistant</p></div><span class="badge">✧ Demo assistant</span></div><div class="chat-messages" id="chat-messages" role="log" aria-label="Conversation with TripPulse AI" aria-live="polite">${chatMessages()}</div><div class="chat-bottom"><form id="chat-form" class="chat-form"><input id="chat-message" name="message" aria-label="Your message to TripPulse AI" placeholder="A question, an idea, a little detour…" maxlength="1500" autocomplete="off" required><button type="submit" class="btn" aria-label="Send message" ${chatBusy?'disabled':''}>${icon('send')}</button></form><p class="simulation-note">Simulated responses · No connected AI service · Verify plans before traveling</p></div></section><aside class="stack"><section class="card card-pad"><span class="eyebrow overline">LET’S MAKE IT YOURS</span><h3>A good place to start</h3><div class="prompt-list">${prompts.map(prompt=>`<button data-prompt="${prompt}" ${chatBusy?'disabled':''}>${prompt}<span>↗</span></button>`).join('')}</div></section><section class="card card-pad"><span class="eyebrow overline">${icon('route')} YOUR ROUTE CONTEXT</span><h3>${escapeHTML(state.trip.start)} → ${escapeHTML(state.trip.destination)}</h3><p class="simulation-note">${state.trip.group} friends · ${escapeHTML(state.trip.budget)} budget · ${escapeHTML(state.trip.style)} pace · ${state.selected.length} selected stops</p><ul class="suggestion-list">${['Start early','Keep beach for sunset light','Avoid adding more than 2 major attractions','Add rest time near Habarana'].map(copy=>`<li>${icon('check')}${copy}</li>`).join('')}</ul>${button('See your itinerary','itinerary','secondary wide','arrow')}</section></aside></div>`;
}
function scrollChat() { const log=$('#chat-messages');if(log)log.scrollTop=log.scrollHeight; }
function updateChat() { if(currentScreen!=='ai')return;$('#chat-messages').innerHTML=chatMessages();$$('[data-prompt], #chat-form button').forEach(button=>button.disabled=chatBusy);scrollChat(); }
function mockReply(message) {
  const text=message.toLowerCase(),summary=scheduleSummary();
  if(/safety|emergency|help|hospital|police|sos|danger|hurt/.test(text))return {text:'Your Safety Center brings emergency actions, trusted contacts, and offline information together. Open it below to review the options. This is a simulation: no call or alert can be sent. In a serious emergency, contact official emergency services immediately.',safety:true};
  if(/late|delay|start/.test(text))return {text:`Your current departure is ${formatTime(startMinutes())}. For a later start, shorten or skip Sigiriya Viewpoint and keep a proper lunch break. Change the time in Create Trip to recalculate the sample schedule. Aim to reach the coast before the evening runs late.`};
  if(/skip|remove|packed/.test(text))return {text:'Keep Dambulla as the main cultural stop and Habarana for lunch. If you need more breathing room, remove Sigiriya Viewpoint first: its detour adds 30 minutes on top of the visit. You can add or remove stops in Places.'};
  if(/cheap|budget|cost/.test(text))return {text:'For a lighter budget, share transport, choose a simple rice-and-curry lunch near Habarana, and keep the free Kantale and beach stops. Admission prices and transport costs are not live in this prototype, so check them separately before you go.'};
  if(/beach|sunset/.test(text))return {text:'Keep the beach for late afternoon and evening light, around 5:00–6:00 PM in this sample plan. Trincomalee is on the east coast, so the sun sets inland rather than over the sea. A quiet beach walk is still a lovely way to end the day.'};
  if(/realistic|balance|improve/.test(text))return {text:`With ${state.selected.length} selected stops and a ${formatTime(startMinutes())} start, your sample check-in is ${formatTime(summary.arrival)}. ${summary.late?'That makes for a late finish. Remove a longer stop or start earlier.':'The pace leaves room for your key stops.'} Keep Sigiriya as a viewpoint visit, take a proper lunch break, and allow flexibility for actual road conditions.`};
  return {text:`For your ${state.trip.start} → ${state.trip.destination} plan, I’d keep a balance of culture, food, and time by the sea. You currently have ${state.selected.length} stops selected. Try asking what to skip, how to adjust for a late start, or where to save money. This demo uses a curated set of route-aware replies.`};
}
function sendMessage(text) {
  const value=text.trim();if(!value||chatBusy)return;
  chat.push({role:'user',text:value.slice(0,1500)});chatBusy=true;
  if($('#chat-message'))$('#chat-message').value='';updateChat();
  setTimeout(()=>{chat.push({role:'assistant',...mockReply(value)});chatBusy=false;updateChat();},1050);
}

const safetyActions=[['phone','Call Police','Review a simulated call action','call-police'],['hospital','Call Ambulance','Urgent support, clearly presented','call-ambulance'],['hospital','Find Nearest Hospital','Sample nearby facility preview','hospital'],['shield','Find Nearest Police Station','Sample local support preview','police-station'],['share','Share My Location','Preview a mock location card','share-location'],['users','Alert Trip Members','Choose recipients, then confirm','alert-members'],['user','Alert Trusted Contacts','Your people back home','alert-contacts'],['download','Offline Emergency Info','Save a reference on your device','emergency-offline']];
function emergencyPreview() { return `<div class="list-row"><span class="icon-tile">${icon('user')}</span><div><strong>${escapeHTML(state.emergency.contact||'No contact set')}</strong><p>Emergency contact · ${state.emergency.enabled?'Enabled':'Disabled'}</p></div></div><div class="detail-grid"><div><small>Blood group</small><strong>${escapeHTML(state.emergency.blood||'Not specified')}</strong></div><div><small>Allergies</small><strong>${escapeHTML(state.emergency.allergies||'Not specified')}</strong></div></div><p class="simulation-note section-space">Emergency profile information is optional and private by default.</p>`; }
function contactsPreview() { return state.contacts.length?state.contacts.slice(0,2).map(contact=>`<div class="list-row"><span class="avatar">${escapeHTML(initials(contact.name))}</span><div><strong>${escapeHTML(contact.name)}</strong><p>${escapeHTML(contact.relationship)} · Sample contact</p></div><span class="badge ${contact.sos?'green':''}">${contact.sos?'SOS ready':'SOS off'}</span></div>`).join(''):emptyState('Your trusted circle starts here.','Add a sample contact to try the flow.','contacts','Add trusted contact'); }
function safety() { return `${heading('A little reassurance, wherever you go.','Clear next steps. Your trusted people. One calm place.',`<span class="badge green">${icon('shield')} Safety tools ready · Demo</span>`)}<section class="safety-banner"><span class="safety-emblem">${icon('shield')}</span><div><span class="eyebrow overline">ALWAYS BY YOUR SIDE</span><h2>When it matters, know where to turn.</h2><p>Keep essential information and the people you trust close to hand, wherever the road takes you.</p></div>${actionButton('Emergency Help','emergency','danger','phone')}</section><div class="notice">${icon('info')}<div><strong>You’re exploring a safety simulation.</strong><p>No calls, messages, or SOS alerts are sent. Locations and facilities are samples; your device location is never accessed.</p></div></div><div class="content-grid"><div class="safety-grid">${safetyActions.map(([symbol,title,copy,action])=>`<button class="safety-action" data-action="${action}"><span class="icon-tile">${icon(symbol)}</span><strong>${title}</strong><small>${copy}</small></button>`).join('')}</div><aside class="stack"><section class="card card-pad">${sectionHeading('Your trusted people','Manage','contacts')}${contactsPreview()}</section><section class="card card-pad">${sectionHeading('Emergency profile','Edit','emergencyProfile')}${emergencyPreview()}</section><section class="card card-pad"><div class="split-row"><div><h3>Ready for the road</h3><p class="simulation-note">${state.emergency.enabled?'✓ Profile enabled':'○ Profile disabled'}<br>${state.contacts.some(contact=>contact.sos)?'✓ SOS contact selected':'○ Add an SOS contact'}<br>✓ Offline reference available</p></div><span class="icon-tile green">${icon('shield')}</span></div></section></aside></div><p class="disclaimer">TripPulse helps you access support faster. In a serious emergency, contact official emergency services immediately.</p>`; }
function memberCard(member) { return `<article class="card member-card"><span class="avatar">${escapeHTML(initials(member.name))}</span><div><div class="split-row"><h3>${escapeHTML(member.name)}${member.role==='Owner'?' <small>(you)</small>':''}</h3><span class="badge ${member.role==='Owner'?'green':''}">${member.role}</span></div><p>${escapeHTML(member.email)}</p>${member.role!=='Owner'?`<div class="button-row">${member.role!=='Admin'?`<button class="text-button" data-promote="${member.id}">Promote to admin</button>`:'<span class="simulation-note">Can manage the trip</span>'}<button class="text-button remove" data-remove-member="${member.id}">Remove member</button></div>`:'<p class="simulation-note">Trip organizer · Full workspace access</p>'}</div></article>`; }
function pendingList() { return state.pending.length?state.pending.map(invite=>`<div class="list-row"><span class="avatar">${escapeHTML(initials(invite.name))}</span><div><strong>${escapeHTML(invite.name)}</strong><p>${escapeHTML(invite.email)} · ${invite.role} · ${invite.expiry}</p></div><button class="text-button" data-cancel-invite="${invite.id}" aria-label="Cancel invitation for ${escapeHTML(invite.name)}">Cancel</button></div>`).join(''):'<p class="simulation-note">No pending invitations. There’s room for another friend.</p>'; }
function members() { return `${heading('Good company makes the journey.','Your people, all in one place. Collaboration is simulated.',button('Invite member','invite','','plus'))}${tripTabs()}${['Owner','Admin','Member','Viewer'].map(role=>{const group=state.members.filter(member=>member.role===role);return `<section><h2 class="member-role-label">${role==='Owner'?'Trip owner':role==='Admin'?'Admins':role==='Member'?'Members':'Viewers'} <span class="badge">${group.length}</span></h2><div class="member-grid">${group.length?group.map(memberCard).join(''):`<p class="simulation-note">No ${role.toLowerCase()}s yet.</p>`}</div></section>`;}).join('')}<div class="equal-grid section-space"><section class="card card-pad">${sectionHeading('Pending invitations')}${pendingList()}</section><section class="card card-pad"><span class="eyebrow overline">BRING SOMEONE ALONG</span><h3>There’s always room for a good friend.</h3><p class="simulation-note">Share a sample invite link and choose their role in the plan. Links are for the demo only.</p><div class="button-row">${actionButton('Copy invite link','copy-invite','soft','copy')}${button('Invite settings','invite','secondary')}</div></section></div>`; }
function inviteLink() { return `https://trippulse.example/invite/weekend-escape?role=${state.inviteRole.toLowerCase()}&expiry=${state.inviteExpiry.replace(' ','-')}`; }
function invite() { return `${heading('Better with your people.','Invite a friend into your next great story.',button('View members','members','secondary','users'))}${tripTabs()}<div class="content-grid"><section class="card card-pad"><span class="icon-tile">${icon('users')}</span><h2 class="section-space">A seat in your next adventure.</h2><p>Share the journey from ${escapeHTML(state.trip.start)} to ${escapeHTML(state.trip.destination)}.</p><div class="invite-link" id="invite-link">${inviteLink()}</div>${actionButton('Copy invite link','copy-invite','','copy')}<div class="form-grid section-space">${selectField('Role offered','inviteRole',['Member','Viewer'],state.inviteRole)}${selectField('Link expires after','inviteExpiry',['24 hours','72 hours','7 days'],state.inviteExpiry)}</div><p class="simulation-note section-space">This is a sample link, not a live invitation. Role and expiry settings update the local preview.</p><div class="divider"></div><h3>Or prepare an email invitation</h3><form id="invite-form"><div class="form-grid section-space">${field('Friend’s name','name','','text','required maxlength="60" placeholder="e.g. Yasara Perera"')}${field('Email address','email','','email','required maxlength="100" placeholder="friend@example.com"')}</div><button type="submit" class="btn secondary section-space">${icon('plus')}Add demo invitation</button></form></section><aside class="stack"><section class="card card-pad">${sectionHeading('Waiting for the crew')}<div id="pending-invites">${pendingList()}</div></section><div class="notice">${icon('lock')}<div><strong>A role for every kind of traveler.</strong><p>Members help shape the plan. Viewers can follow along. Owners and admins manage the workspace.</p></div></div></aside></div>`; }
function exploreResults() {
  const matches=destinations.filter(destination=>(exploreCategory==='All'||destination.category===exploreCategory)&&`${destination.name} ${destination.category} ${destination.subtitle}`.toLowerCase().includes(exploreQuery.toLowerCase()));
  return matches.length?`<div class="discover-grid">${matches.map(destinationCard).join('')}</div>`:emptyState('A little further afield?','No destinations match those filters. Try another place name or choose All.');
}
function explore() { return `${heading('One island. So many ways to feel it.','From tea-covered hills to salt-in-your-hair afternoons. Find what moves you.')}<section class="hero explore-hero"><div class="hero-art">${scene('hills')}</div><div class="hero-copy"><span class="eyebrow">${icon('compass')} FOLLOW YOUR CURIOSITY</span><h2>Some places stay with you.</h2><p>Discover your next “we should go there” moment.</p></div></section><div class="explore-toolbar"><label class="search-field">${icon('search')}<input id="explore-search" type="search" aria-label="Search destinations" placeholder="Search for a place, a feeling, a little escape…" value="${escapeHTML(exploreQuery)}"></label><button class="btn secondary" data-action="show-saved">${icon('bookmark')}Saved · ${state.savedDestinations.length}</button></div><div class="chips">${['All','Beaches','Nature','Heritage','Wildlife'].map(category=>`<button class="chip" data-category="${category}" aria-pressed="${exploreCategory===category}">${category}</button>`).join('')}</div><section class="section-space">${sectionHeading('Popular destinations')}<div id="explore-results" aria-live="polite">${exploreResults()}</div></section><section class="section-space">${sectionHeading('Nearby, along your route','All route places','suggestions')}<div class="equal-grid">${[places[1],places[4]].map(place=>`<article class="card guide-card"><div class="preview-thumb">${scene(place.scene)}</div><div><h3>${place.name}</h3><p>${place.detour} off the sample route · ${place.duration} min</p></div><button class="text-button" data-place="${place.id}">Take a look ↗</button></article>`).join('')}</div></section><section id="saved-section" class="section-space">${sectionHeading('Keep the good ideas close')}<div class="saved-grid">${state.savedDestinations.length?destinations.filter(destination=>state.savedDestinations.includes(destination.id)).map(destination=>`<article class="card guide-card"><div class="preview-thumb">${scene(destination.scene)}</div><div><h3>${destination.name}</h3><p>${destination.subtitle}</p></div><button class="text-button" data-destination="${destination.id}">View guide ↗</button></article>`).join(''):emptyState('Your collection starts with a little curiosity.','Open a destination and save it for another day.')}</div></section><section class="section-space">${sectionHeading('A little inspiration for the road')}<div class="equal-grid"><article class="card card-pad"><span class="eyebrow overline">THE WEEKEND EDIT</span><h3>48 hours of coast & culture</h3><p class="simulation-note">A temple morning, a leisurely lunch, and a slower evening in Trincomalee.</p><button class="text-button" data-destination="trinco">Read destination guide ↗</button></article><article class="card card-pad"><span class="eyebrow overline">TAKE THE SCENIC WAY</span><h3>A slower kind of hill-country escape</h3><p class="simulation-note">Misty viewpoints, tea country, and time to simply look around.</p><button class="text-button" data-destination="ella">Read destination guide ↗</button></article></div></section>`; }
function notifications() {
  const unread=notificationData.filter(item=>!state.readNotifications.includes(item.id));
  const visible=unreadOnly?unread:notificationData;
  return `${heading('A few things from your travel world.','The latest from your crew, your route, and your companion.',actionButton('Mark all as read','read-all','secondary','check'))}<div class="notification-tabs"><button class="chip" data-notification-filter="all" aria-pressed="${!unreadOnly}">All updates · ${notificationData.length}</button><button class="chip" data-notification-filter="unread" aria-pressed="${unreadOnly}">Unread · ${unread.length}</button></div><div class="notification-list">${visible.length?visible.map(item=>`<article class="card notification-card ${state.readNotifications.includes(item.id)?'':'unread'}"><span class="icon-tile ${item.icon==='shield'?'green':''}">${icon(item.icon)}</span><div><h3>${item.title} ${state.readNotifications.includes(item.id)?'':'<span class="badge">New</span>'}</h3><p>${item.text}</p><button class="text-button" data-notification="${item.id}">Take a look ${icon('arrow')}</button></div><time>${item.time}</time></article>`).join(''):emptyState('All caught up.','A little less to check. A little more time to plan.','dashboard','Back to dashboard')}</div>`;
}
function profile() { return `${heading('Make yourself at home.','Your preferences, your people, your peace of mind.')}<div class="content-grid"><div class="stack"><section class="card card-pad"><div class="profile-heading"><span class="avatar avatar-main">${escapeHTML(initials(state.profile.name))}</span><div><h2>${escapeHTML(state.profile.name)}</h2><p>Curious by nature. Always up for a detour.</p></div></div><form id="profile-form"><div class="form-grid">${field('Name','name',state.profile.name,'text','required maxlength="60" autocomplete="name"')}${field('Email','email',state.profile.email,'email','required maxlength="100" autocomplete="email"')}${field('Home city','city',state.profile.city,'text','required maxlength="60"')}${selectField('Preferred language','language',['English','Sinhala','Tamil'],state.profile.language)}</div><p class="simulation-note section-space">Preferences stay on this device. Translations are not included in the demo.</p><button type="submit" class="btn section-space">Save profile</button></form></section><section class="card card-pad"><h2>The little preferences.</h2><div class="setting-row"><div><strong>Dark mode</strong><p>A softer view for after-hours planning.</p></div><button class="toggle" role="switch" aria-checked="${state.theme==='dark'}" aria-label="Dark mode" data-action="theme"></button></div><div class="setting-row"><div><strong>Trip notifications</strong><p>Local preference. No push notifications are sent.</p></div><button class="toggle" role="switch" aria-checked="${state.notificationsEnabled}" aria-label="Trip notifications" data-action="toggle-notifications"></button></div><div class="setting-row"><div><strong>Private profile</strong><p>Privacy preview. All prototype data stays in this browser.</p></div><button class="toggle" role="switch" aria-checked="${state.privateProfile}" aria-label="Private profile" data-action="toggle-privacy"></button></div><div class="setting-row"><div><strong>A little more about TripPulse</strong><p>Your journey, connected.</p></div><button class="text-button" data-nav="welcome">Welcome ↗</button></div>${actionButton('Logout of demo','logout','secondary')}</section></div><aside class="stack"><section class="card card-pad">${sectionHeading('Emergency profile','Manage','emergencyProfile')}${emergencyPreview()}</section><section class="card card-pad">${sectionHeading('Your trusted people','Manage','contacts')}${contactsPreview()}</section><div class="notice">${icon('lock')}<div><strong>Your space, on your device.</strong><p>No account, tracking, or external service is connected. Use fictional details while exploring the prototype.</p></div></div></aside></div>`; }
function emergencyProfile() { return `${heading('A little information can help.','Keep useful details together. Optional, private, and local to this demo.',button('Back to Safety','safety','secondary','shield'))}<div class="content-grid"><form id="emergency-form" class="card form-card"><div class="split-row"><h2>Your emergency profile</h2><span class="badge ${state.emergency.enabled?'green':''}">${state.emergency.enabled?'Enabled':'Disabled'}</span></div><div class="setting-row"><div><strong>Enable emergency profile</strong><p>Include these details in your local emergency reference.</p></div><button type="button" class="toggle" role="switch" aria-checked="${state.emergency.enabled}" aria-label="Enable emergency profile" data-action="toggle-emergency"></button></div><div class="form-grid section-space">${field('Emergency contact name','contact',state.emergency.contact,'text','maxlength="80"')}${field('Emergency contact phone','phone',state.emergency.phone,'text','maxlength="60"')}${selectField('Blood group','blood',['Not specified','A+','A−','B+','B−','AB+','AB−','O+','O−'],state.emergency.blood||'Not specified')}${selectField('Preferred emergency language','language',['English','Sinhala','Tamil'],state.emergency.language)}<label class="field full">Allergies<input name="allergies" value="${escapeHTML(state.emergency.allergies)}" maxlength="250" placeholder="Optional sample information"></label><label class="field full">Medical notes<textarea name="notes" rows="3" maxlength="800">${escapeHTML(state.emergency.notes)}</textarea></label></div><p class="simulation-note section-space">Emergency profile information is optional and private by default. This prototype stores unencrypted local data; use fictional details.</p><div class="form-actions">${actionButton('Delete profile','delete-emergency','danger-soft')}<button type="submit" class="btn">Save profile ${icon('check')}</button></div></form><aside class="stack"><div class="notice">${icon('lock')}<div><strong>Only what you’re comfortable sharing.</strong><p>All fields are optional. Disabling the profile excludes its details from the offline emergency download. Deleting it clears the saved fields.</p></div></div><section class="card card-pad"><span class="icon-tile">${icon('users')}</span><h3 class="section-space">Keep your trusted circle close.</h3><p class="simulation-note">Choose which of your sample contacts appear in the SOS confirmation flow.</p>${button('Manage trusted contacts','contacts','soft wide','arrow')}</section></aside></div>`; }
function contacts() { return `${heading('Your people, wherever you go.','The familiar faces you’d want to reach when it matters.',actionButton('Add contact','add-contact','','plus'))}<div class="notice">${icon('shield')}<div><strong>A trusted circle for a calmer journey.</strong><p>These contacts are fictional. SOS settings control the demo recipient preview; no alerts or messages are sent.</p></div></div><div class="equal-grid">${state.contacts.length?state.contacts.map(contact=>`<article class="card contact-card"><div class="contact-top"><span class="avatar">${escapeHTML(initials(contact.name))}</span><div><h3>${escapeHTML(contact.name)}</h3><p>${escapeHTML(contact.relationship)}</p></div></div><span class="badge ${contact.sos?'green':''}">${icon(contact.sos?'shield':'lock')}SOS ${contact.sos?'enabled':'disabled'}</span><p class="contact-phone">${icon('phone')} ${escapeHTML(contact.phone)}</p><div class="button-row"><button class="text-button" data-edit-contact="${contact.id}">Edit contact ↗</button><button class="btn secondary small" data-delete-contact="${contact.id}">Delete</button></div></article>`).join(''):emptyState('A trusted circle starts with one person.','Add a fictional contact to explore the safety flow.')}</div><div class="button-row section-space">${button('Back to Safety','safety','secondary','shield')}${button('Emergency profile','emergencyProfile','soft','user')}</div>`; }
const screens={dashboard,welcome,trips,create:createTrip,overview,suggestions,itinerary,map:mapScreen,ai:aiScreen,safety,members,invite,explore,notifications,profile,emergencyProfile,contacts};

// Dialogs use the native focus trap and restore focus when dismissed.
function openModal(title,html) {
  if(!$('#modal').open)modalOrigin=document.activeElement;
  $('#modal-title').textContent=title;$('#modal-body').innerHTML=html;
  hydrateIcons();if(!$('#modal').open)$('#modal').showModal();
  $('#modal [autofocus], #modal-body input, #modal-body button, #modal .icon-button')?.focus({preventScroll:true});
}
function closeModal(restore=true) { $('#modal').close();if(restore)(modalOrigin?.isConnected?modalOrigin:$('#main')).focus({preventScroll:true}); }
function showPlace(id) {
  const place=places.find(item=>item.id===id);if(!place)return;
  const selected=state.selected.includes(id);
  openModal(place.name,`<div class="modal-place-art">${scene(place.scene)}</div><div class="split-row"><span class="badge">${place.category} · Stop 0${place.id}</span><span class="badge amber">${icon('star')}${place.rating} · Mock rating</span></div><p class="section-space">${place.reason}</p><div class="detail-grid modal-details">${[['Best time',place.best],['Visit duration',`${place.duration} minutes`],['Distance from route',place.detour],['Extra travel time',`${place.extra} minutes`],['Price level',`${place.price} · Sample`],['Why recommended','Fits your route & interests']].map(([label,value])=>`<div><small>${label}</small><strong>${value}</strong></div>`).join('')}</div><p class="simulation-note">${place.note} All place information is illustrative.</p><div class="button-row"><button class="btn ${selected?'soft':''}" data-modal-toggle="${id}" aria-pressed="${selected}">${icon(selected?'check':'plus')}${selected?'Added · Remove':'Add to trip'}</button><button class="btn secondary" data-place-map="${id}">${icon('map')}Open map</button></div>`);
}
function showDestination(id) {
  const destination=destinations.find(item=>item.id===id);if(!destination)return;
  const saved=state.savedDestinations.includes(id);
  openModal(`A little guide to ${destination.name}`,`<div class="modal-place-art">${scene(destination.scene)}</div><span class="badge">${destination.category}</span><h3 class="section-space">${destination.subtitle}</h3><p class="section-space">${destination.copy}</p><div class="notice section-space">${icon('compass')}<div><strong>Make room for the unplanned.</strong><p>This is a sample destination guide. Weather, opening hours, availability, and prices are not live.</p></div></div><div class="button-row"><button class="btn ${saved?'soft':''}" data-save-destination="${id}" aria-pressed="${saved}">${icon('bookmark')}${saved?'Saved · Remove':'Save destination'}</button>${button('Start a trip','create','secondary','plus')}</div>`);
}
function emergencyModal() { openModal('Emergency Help',`<p>Clear actions, in one place. <strong>This is a demo: no calls or alerts are sent.</strong></p><div class="location-preview">${icon('pin')} Current location · Mock<strong>Near Dambulla, Central Province</strong><small>7.8742° N, 80.6511° E · Not your actual device location</small></div><div class="modal-options">${[['phone','Call Police','call-police'],['hospital','Call Ambulance','call-ambulance'],['hospital','Find Nearest Hospital','hospital'],['shield','Find Nearest Police Station','police-station'],['share','Share Location','share-location'],['shield','Send SOS Alert','sos']].map(([symbol,label,action])=>actionButton(label,action,action==='sos'?'danger':'secondary',symbol)).join('')}</div><p class="simulation-note">SOS always asks you to choose recipients and confirm first.</p>`); }
function confirmSOS(audience='all') {
  const recipients=state.contacts.filter(contact=>contact.sos);
  openModal('Confirm your SOS preview',`<div class="sos-emblem">!</div><p>Prepare a help request with the <strong>mock Dambulla location</strong>. Choose who appears in this simulation.</p><form id="sos-form"><div class="location-preview"><label class="recipient-row"><input type="checkbox" name="members" ${audience!=='contacts'&&state.members.length>1?'checked':''} ${state.members.length<2?'disabled':''}><span><strong>Trip members</strong><small>${state.members.filter(member=>member.role!=='Owner').map(member=>escapeHTML(member.name)).join(', ')||'No other members yet'}</small></span></label><label class="recipient-row"><input type="checkbox" name="contacts" ${audience!=='members'&&recipients.length?'checked':''} ${!recipients.length?'disabled':''}><span><strong>Trusted contacts</strong><small>${recipients.map(contact=>escapeHTML(contact.name)).join(', ')||'No SOS-enabled contacts yet'}</small></span></label></div><p class="simulation-note">Nothing is sent to these people or to emergency services. You can cancel at any time before confirming.</p><div class="button-row section-space"><button type="button" class="btn secondary" data-action="cancel-sos">Cancel</button><button type="submit" class="btn danger">Confirm demo SOS</button></div></form>`);
}
function facilityPreview(kind) {
  if(kind==='food'||kind==='hotel') { openModal(kind==='food'?'A lunch stop near Habarana':'A place to slow down',`<div class="modal-place-art">${scene(kind==='food'?'forest':'beach')}</div><span class="badge">${kind==='food'?'Food layer':'Hotel layer'} · Sample</span><h3 class="section-space">${kind==='food'?'Village rice & curry stop':'Coastal guesthouse preview'}</h3><p class="section-space">${kind==='food'?'A relaxed lunch break with your crew. Allow about 60 minutes before the coastal leg.':'A sample stay near Trincomalee beach. Leave time to check in and settle after the drive.'}</p><p class="simulation-note section-space">Illustrative pin only. No real business, reservation, availability, or live directions.</p>${button('View itinerary','itinerary','soft wide','route')}`);return; }
  openModal(kind==='hospital'?'Nearest hospital · Demo preview':'Nearest police station · Demo preview',`<div class="notice">${icon('info')}<div><strong>Illustrative results, not a live search.</strong><p>Your location was not accessed. Distance, availability, and directions are unverified.</p></div></div><div class="location-preview"><span class="icon-tile">${icon(kind==='hospital'?'hospital':'shield')}</span><strong>${kind==='hospital'?'Sample district hospital':'Sample local police station'}</strong><small>Near the mock Dambulla location · ${kind==='hospital'?'2.4 km':'1.8 km'} sample distance</small></div><p>For actual assistance, contact official services or use a trusted live map.</p><div class="button-row">${actionButton('Back to Emergency Help','emergency','secondary','arrow')}${actionButton('Close preview','close-modal','soft')}</div>`);
}
function contactForm(id) {
  const contact=state.contacts.find(item=>item.id===id)||{name:'',relationship:'Friend',phone:'',sos:true};
  openModal(id?'Edit trusted contact':'Add someone you trust',`<p>Use fictional details for this local prototype.</p><form id="contact-form" data-id="${id||''}"><div class="form-grid">${field('Full name','name',contact.name,'text','required maxlength="80"')}${selectField('Relationship','relationship',['Family','Friend','Partner','Other'],contact.relationship)}<label class="field full">Phone or sample contact label<input name="phone" value="${escapeHTML(contact.phone)}" maxlength="60" required placeholder="e.g. Demo contact · no number"></label></div><label class="recipient-row section-space"><input type="checkbox" name="sos" ${contact.sos?'checked':''}>Include in SOS recipient preview</label><div class="button-row section-space"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn">${id?'Save contact':'Add contact'}</button></div></form>`);
}
function downloadFile(name,content) {
  const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));
  const link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function offlinePlan() {
  downloadFile('TripPulse-modern-itinerary.txt',`TRIPPULSE — YOUR OFFLINE TRIP PLAN\n\n${state.trip.name}\n${state.trip.start} → ${state.trip.destination}\n${dateText()} | ${state.trip.group} travelers | ${state.trip.transport}\n${state.trip.budget} budget | ${state.trip.style} pace\n\n${buildSchedule().map(item=>`${formatTime(item.time)} — ${item.title}\n${item.travel} min travel | ${item.duration} min visit\n${item.note}`).join('\n\n')}\n\nLOCAL PROTOTYPE: Times and places use the Kandy → Trincomalee driving demo. Not live routing. Check conditions before travel. No emergency alerts or calls are available in this file. In a serious emergency, contact official emergency services immediately.`);
  toast('Your offline itinerary is ready to download.');
}
function emergencyDownload() {
  const profile=state.emergency;
  downloadFile('TripPulse-modern-emergency-info.txt',`TRIPPULSE — OFFLINE EMERGENCY REFERENCE\n\nDEMO ONLY — no live services, calls, messages, or location tracking.\n\nIn a serious emergency, contact official emergency services immediately using your phone.\nProvide your actual location, the nature of the emergency, and a callback number.\n\nBefore you travel: verify local emergency numbers, save actual contact numbers, download a real offline map, and agree on a group meeting point.\n\nSAMPLE TRUSTED CONTACTS\n${state.contacts.map(contact=>`${contact.name} | ${contact.relationship} | ${contact.phone} | SOS preview ${contact.sos?'enabled':'disabled'}`).join('\n')||'No contacts saved.'}\n\n${profile.enabled?`SAMPLE EMERGENCY PROFILE\nContact: ${profile.contact||'Not specified'}\nPhone: ${profile.phone||'Not specified'}\nBlood group: ${profile.blood||'Not specified'}\nAllergies: ${profile.allergies||'Not specified'}\nNotes: ${profile.notes||'Not specified'}\nLanguage: ${profile.language}`:'Emergency profile disabled — personal profile details excluded.'}\n\nMock location: Near Dambulla, 7.8742° N, 80.6511° E. NOT your actual location.\nKeep this downloaded file private; it may contain details you entered.`);
  toast('Offline emergency reference is ready to download.');
}
async function copyText(value,label='Sample text') {
  try { if(!navigator.clipboard)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(value);toast(`${label} copied. Nothing was sent.`); }
  catch { openModal('Copy your sample text',`<p>Your browser hasn’t enabled clipboard access for this local file. Select and copy the text below.</p><textarea class="section-space" rows="5" readonly aria-label="Text to copy">${escapeHTML(value)}</textarea>${actionButton('Done','close-modal','soft wide')}`);$('#modal textarea').focus();$('#modal textarea').select(); }
}
function captureDraft() { const form=$('#trip-form');if(!form)return;for(const [key,value] of new FormData(form))draft[key]=key==='group'?Number(value):value.trim(); }
function captureEmergency() { const form=$('#emergency-form');if(form)Object.assign(state.emergency,Object.fromEntries(new FormData(form))); }
function refreshKeepPosition(selector) { const position=window.scrollY;render();window.scrollTo({top:position,behavior:'instant'});if(selector)$(selector)?.focus({preventScroll:true}); }
function togglePlace(id) { state.selected=state.selected.includes(id)?state.selected.filter(value=>value!==id):[...state.selected,id].sort((a,b)=>a-b);persist(); }
function handleAction(action) {
  switch(action) {
    case 'theme':state.theme=state.theme==='light'?'dark':'light';persist();updateTheme();break;
    case 'suggest':navigate('suggestions');toast('Six curated suggestions are ready, in route order.');break;
    case 'form-back':captureDraft();if(formStep>1){formStep--;render();$('#trip-form input, #trip-form button')?.focus();}else navigate('trips');break;
    case 'generate':navigate('itinerary');toast(`Your itinerary is ready with ${state.selected.length} selected stops.`);break;
    case 'recalculate':refreshKeepPosition('[data-action="recalculate"]');toast('Schedule recalculated from your departure time and selected stops.');break;
    case 'save-offline':offlinePlan();break;
    case 'close-modal':closeModal();break;
    case 'emergency':emergencyModal();break;
    case 'sos':confirmSOS();break;
    case 'alert-members':confirmSOS('members');break;
    case 'alert-contacts':confirmSOS('contacts');break;
    case 'cancel-sos':closeModal();toast('SOS preview canceled. Nothing was prepared or sent.');break;
    case 'call-police':case 'call-ambulance':openModal(action==='call-police'?'Call Police · Simulation':'Call Ambulance · Simulation',`<span class="icon-tile">${icon('phone')}</span><h3 class="section-space">No call has been placed.</h3><p class="section-space">This prototype previews the call action. In an emergency, use your phone to contact official ${action==='call-police'?'police':'ambulance'} services immediately.</p><div class="button-row">${actionButton('Back to Emergency Help','emergency','secondary')}${actionButton('Understood','close-modal','soft')}</div>`);break;
    case 'hospital':case 'police-station':facilityPreview(action);break;
    case 'share-location':openModal('Share My Location · Preview',`<p>Your device location has not been accessed.</p><div class="location-preview">${icon('pin')} Sample location<strong>Near Dambulla, Central Province</strong><small>7.8742° N, 80.6511° E · Mock coordinates only</small></div><p>No location has been shared. You can copy a clearly labeled sample card.</p><div class="button-row">${actionButton('Copy mock location','copy-location','','copy')}${actionButton('Cancel','close-modal','secondary')}</div>`);break;
    case 'copy-location':copyText('TRIPPULSE DEMO LOCATION ONLY — Near Dambulla, Sri Lanka. 7.8742° N, 80.6511° E. NOT a live or actual device location.','Mock location');break;
    case 'emergency-offline':emergencyDownload();break;
    case 'copy-invite':copyText(`TripPulse demo invitation: ${state.trip.name}\n${inviteLink()}\nRole: ${state.inviteRole} | Expires: ${state.inviteExpiry}\nSample link only — no live group, email, or invitation service.`,'Sample invitation');break;
    case 'read-all':state.readNotifications=notificationData.map(item=>item.id);persist();refreshKeepPosition('[data-action="read-all"]');toast('All notifications marked as read.');break;
    case 'show-saved':$('#saved-section')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});break;
    case 'toggle-notifications':state.notificationsEnabled=!state.notificationsEnabled;persist();$('[data-action="toggle-notifications"]').setAttribute('aria-checked',String(state.notificationsEnabled));toast(`Demo notification preference ${state.notificationsEnabled?'enabled':'muted'}.`);break;
    case 'toggle-privacy':state.privateProfile=!state.privateProfile;persist();$('[data-action="toggle-privacy"]').setAttribute('aria-checked',String(state.privateProfile));toast('Privacy preference saved locally. No information is shared.');break;
    case 'toggle-emergency':captureEmergency();state.emergency.enabled=!state.emergency.enabled;persist();refreshKeepPosition('[data-action="toggle-emergency"]');toast(`Emergency profile ${state.emergency.enabled?'enabled':'disabled'} for the local reference.`);break;
    case 'delete-emergency':openModal('Delete emergency profile?',`<p>This clears the emergency fields saved in this prototype. Your trusted contacts will remain.</p><div class="button-row">${actionButton('Keep profile','close-modal','secondary')}${actionButton('Delete profile','confirm-delete-emergency','danger')}</div>`);break;
    case 'confirm-delete-emergency':state.emergency={contact:'',phone:'',blood:'Not specified',allergies:'',notes:'',language:'English',enabled:false};persist();closeModal(false);render();$('#main').focus();toast('Emergency profile deleted from this local prototype.');break;
    case 'add-contact':contactForm();break;
    case 'logout':openModal('Leave the demo workspace?',`<p>There is no signed-in account. Return to the welcome screen and keep your local trip for later.</p><div class="button-row">${actionButton('Stay here','close-modal','secondary')}${actionButton('Return to welcome','confirm-logout','')}</div>`);break;
    case 'confirm-logout':navigate('welcome');toast('Your local plan is saved for your next visit.');break;
  }
}

// Delegated events keep the UI readable and avoid per-render listener duplication.
document.addEventListener('click',event=>{
  const target=event.target.closest('button, a');if(!target)return;
  if(target.dataset.nav){navigate(target.dataset.nav);return;}
  if(target.dataset.action){event.preventDefault();handleAction(target.dataset.action);return;}
  if(target.hasAttribute('data-toggle-place')){const id=Number(target.dataset.togglePlace);togglePlace(id);refreshKeepPosition(`[data-toggle-place="${id}"]`);return;}
  if(target.hasAttribute('data-modal-toggle')){const id=Number(target.dataset.modalToggle);togglePlace(id);refreshKeepPosition();showPlace(id);$('[data-modal-toggle]')?.focus();return;}
  if(target.dataset.place){showPlace(Number(target.dataset.place));return;}
  if(target.dataset.placeMap){mapStop=Number(target.dataset.placeMap);layers.add('Places');navigate('map');return;}
  if(target.dataset.budget||target.dataset.style||target.dataset.interest){
    captureDraft();const value=target.dataset.interest;
    if(target.dataset.budget)draft.budget=target.dataset.budget;
    if(target.dataset.style)draft.style=target.dataset.style;
    if(value)draft.interests=draft.interests.includes(value)?draft.interests.filter(item=>item!==value):[...draft.interests,value];
    const attribute=target.dataset.budget?'budget':target.dataset.style?'style':'interest';
    refreshKeepPosition(`[data-${attribute}="${target.dataset[attribute]}"]`);return;
  }
  if(target.dataset.layer){const value=target.dataset.layer;layers.has(value)?layers.delete(value):layers.add(value);refreshKeepPosition(`[data-layer="${value}"]`);return;}
  if(target.hasAttribute('data-map-stop')){mapStop=Number(target.dataset.mapStop);$('#map-visual').innerHTML=mapCanvas();$('#map-detail').innerHTML=mapSheet();$(`#map-visual [data-map-stop="${mapStop}"]`)?.focus({preventScroll:true});return;}
  if(target.dataset.facility){facilityPreview(target.dataset.facility);return;}
  if(target.dataset.prompt){sendMessage(target.dataset.prompt);return;}
  if(target.dataset.category){exploreCategory=target.dataset.category;refreshKeepPosition(`[data-category="${exploreCategory}"]`);return;}
  if(target.dataset.destination){showDestination(target.dataset.destination);return;}
  if(target.dataset.saveDestination){const id=target.dataset.saveDestination;state.savedDestinations=state.savedDestinations.includes(id)?state.savedDestinations.filter(value=>value!==id):[...state.savedDestinations,id];persist();refreshKeepPosition();showDestination(id);$('[data-save-destination]')?.focus();toast(state.savedDestinations.includes(id)?'A little inspiration, saved for later.':'Destination removed from your saved collection.');return;}
  if(target.dataset.notificationFilter){unreadOnly=target.dataset.notificationFilter==='unread';refreshKeepPosition(`[data-notification-filter="${target.dataset.notificationFilter}"]`);return;}
  if(target.dataset.notification){const item=notificationData.find(item=>item.id===Number(target.dataset.notification));if(!state.readNotifications.includes(item.id))state.readNotifications.push(item.id);persist();navigate(item.nav);return;}
  if(target.dataset.promote){const member=state.members.find(member=>member.id===Number(target.dataset.promote));if(member){member.role='Admin';persist();refreshKeepPosition();toast(`${member.name} is now a demo trip admin.`);}return;}
  if(target.dataset.removeMember){const member=state.members.find(member=>member.id===Number(target.dataset.removeMember));if(!member||member.role==='Owner')return;openModal('Remove this trip member?',`<p>Remove <strong>${escapeHTML(member.name)}</strong> from this local trip workspace?</p><div class="button-row">${actionButton('Keep member','close-modal','secondary')}<button class="btn danger" data-confirm-remove-member="${member.id}">Remove member</button></div>`);return;}
  if(target.dataset.confirmRemoveMember){state.members=state.members.filter(member=>member.id!==Number(target.dataset.confirmRemoveMember)||member.role==='Owner');persist();closeModal(false);refreshKeepPosition();$('#main').focus({preventScroll:true});toast('Member removed from the demo workspace.');return;}
  if(target.dataset.cancelInvite){state.pending=state.pending.filter(invite=>invite.id!==Number(target.dataset.cancelInvite));persist();refreshKeepPosition();toast('Demo invitation canceled.');return;}
  if(target.dataset.editContact){contactForm(Number(target.dataset.editContact));return;}
  if(target.dataset.deleteContact){const contact=state.contacts.find(contact=>contact.id===Number(target.dataset.deleteContact));if(contact)openModal('Delete trusted contact?',`<p>Remove <strong>${escapeHTML(contact.name)}</strong> from your local trusted contacts and SOS preview?</p><div class="button-row">${actionButton('Keep contact','close-modal','secondary')}<button class="btn danger" data-confirm-delete-contact="${contact.id}">Delete contact</button></div>`);return;}
  if(target.dataset.confirmDeleteContact){state.contacts=state.contacts.filter(contact=>contact.id!==Number(target.dataset.confirmDeleteContact));persist();closeModal(false);render();$('#main').focus({preventScroll:true});toast('Trusted contact deleted.');}
});
document.addEventListener('input',event=>{
  if(event.target.id==='explore-search'){exploreQuery=event.target.value;$('#explore-results').innerHTML=exploreResults();}
});
document.addEventListener('change',event=>{
  if(['inviteRole','inviteExpiry'].includes(event.target.name)){state[event.target.name]=event.target.value;persist();$('#invite-link').textContent=inviteLink();}
});
document.addEventListener('submit',event=>{
  const form=event.target;
  if(!['trip-form','chat-form','profile-form','emergency-form','contact-form','invite-form','sos-form'].includes(form.id))return;
  event.preventDefault();if(!form.reportValidity())return;
  const values=Object.fromEntries([...new FormData(form)].map(([key,value])=>[key,value.trim()]));
  switch(form.id){
    case 'trip-form':
      captureDraft();
      if(!draft.name||!draft.start||!draft.destination){toast('Please enter a trip name, start, and destination.');return;}
      if(draft.start.toLowerCase()===draft.destination.toLowerCase()){toast('Choose a destination different from your start.');return;}
      if(formStep<3){formStep++;render();$('#trip-form input, #trip-form button')?.focus();}
      else{state.trip=structuredClone(draft);persist();navigate('overview');toast('Your trip workspace is ready. Let the good planning begin.');}
      break;
    case 'chat-form':sendMessage(values.message);break;
    case 'profile-form':
      if(!values.name||!values.city){toast('Please enter a name and home city.');return;}
      state.profile=values;state.members=state.members.map(member=>member.role==='Owner'?{...member,name:values.name,email:values.email}:member);persist();refreshKeepPosition('#profile-form button');toast('Profile saved on this device.');break;
    case 'emergency-form':Object.assign(state.emergency,values);persist();toast('Emergency profile saved on this device.');break;
    case 'contact-form':{
      if(!values.name||!values.phone){toast('Please add a name and phone or sample contact label.');return;}
      const id=Number(form.dataset.id)||Date.now(),contact={id,name:values.name,relationship:values.relationship,phone:values.phone,sos:values.sos==='on'};
      state.contacts=state.contacts.some(item=>item.id===id)?state.contacts.map(item=>item.id===id?contact:item):[...state.contacts,contact];persist();closeModal(false);render();$('#main').focus();toast('Trusted contact saved locally.');break;
    }
    case 'invite-form':
      if(!values.name){toast('Please enter your friend’s name.');return;}
      if(state.pending.some(item=>item.email.toLowerCase()===values.email.toLowerCase())||state.members.some(item=>item.email.toLowerCase()===values.email.toLowerCase())){toast('This person is already a member or has a pending invitation.');return;}
      state.pending.push({id:Date.now(),...values,role:state.inviteRole,expiry:state.inviteExpiry});persist();refreshKeepPosition('#invite-form input');toast('Demo invitation prepared. No email was sent.');break;
    case 'sos-form':{
      if(!values.members&&!values.contacts){
        let error=$('#sos-error');
        if(!error){error=document.createElement('p');error.id='sos-error';error.className='notice warning';error.setAttribute('role','alert');form.prepend(error);}
        error.textContent='Select at least one recipient group, or cancel.';
        return;
      }
      const recipients=[values.members?'trip members':'',values.contacts?'SOS-enabled trusted contacts':''].filter(Boolean).join(' and ');
      openModal('Your SOS preview is prepared',`<span class="icon-tile green">${icon('check')}</span><h3 class="section-space">Confirmation complete.</h3><p class="section-space">A demo help request was prepared for <strong>${recipients}</strong> with the mock Dambulla location.</p><div class="notice section-space">${icon('info')}<div><strong>No alert was sent. No one was contacted.</strong><p>In a serious emergency, contact official emergency services immediately.</p></div></div>${button('Back to Safety Center','safety','soft wide','shield')}`);
      toast('SOS alert prepared for selected contacts — demo only; nothing sent.');break;
    }
  }
});
$('#modal').addEventListener('click',event=>{if(event.target!==$('#modal'))return;const rect=$('#modal').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();});
$('#modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
window.addEventListener('popstate',()=>navigate(location.hash.slice(1),false));
window.addEventListener('hashchange',()=>{const screen=location.hash.slice(1);if(screen!==currentScreen)navigate(screen,false);});
currentScreen=screens[location.hash.slice(1)]?location.hash.slice(1):'dashboard';
render();
